//! Transistors (manual 4.8): each a node shape, and its variants by its options (`bodydiode`,
//! `bulk`, `doublegate`…), named `npn|bodydiode`.
//!
//! Measured on what CircuiTikZ 1.8.7 draws (`tools/oracle/`), at the default size, in
//! `bipoles/length`; the text goes right of the `text` anchor and does not count in the picture's
//! size; a `Channel` is a depletion channel or a pmos bubble, dark unless filled. The JFETs are
//! measured too with `transistors/jfet gate height` changed (`njfet@jfet gate height`).

// measured numbers, some of which happen to be close to constants like π/6
#![allow(clippy::approx_constant)]

